import sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

filepath = r'C:\Users\ZR\Desktop\钟锐的个人网站\daily_data.js'
with open(filepath, 'r', encoding='utf-8') as f:
    lines = f.readlines()

# Find section start lines
def find_section_starts():
    starts = {}
    targets = ['stock: {', 'anime: {', 'music: {', 'novel: {', 'gaming: {',
               'learning: {', 'beer: {', 'fashion: {', 'fitness: {', 'diet: {',
               'career: {', 'car: {', 'house: {', '"life-tips": {', 'movie: {',
               '"ai-track": {', 'news: {']
    for i, line in enumerate(lines):
        s = line.strip()
        if s in targets:
            key = s.replace('"','').replace(': {','')
            starts[key] = i
    return starts

def find_section_end(start_line):
    depth = 0
    for i in range(start_line, len(lines)):
        depth += lines[i].count('{') - lines[i].count('}')
        if depth <= 0:
            return i
    return len(lines) - 1

starts = find_section_starts()
print("Found sections:", list(starts.keys()))

